def main():
    total_added = 0
    for lang in LANGS:
        path = f'lang/{lang}.json'
        with io.open(path, encoding='utf-8') as f:
            data = json.load(f, object_pairs_hook=collections.OrderedDict)
        added = 0
        for key, fb in MISSING.items():
            if key in data:
                continue
            if lang == 'ar':
                data[key] = fb
                added += 1
            elif lang == 'en':
                # English: prefer the literal fallback if it is already English
                v = fb if fb and all(ord(c) < 0x590 for c in fb) else T.get(key, {}).get('en', fb)
                data[key] = v
                added += 1
            else:
                # Prefer the explicit table, fall back to English, then fallback text
                v = T.get(key, {}).get(lang) or T.get(key, {}).get('en') or fb
                data[key] = v
                added += 1
        with io.open(path, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
            f.write('\n')
        total_added += added
        print(f'{lang}: +{added} keys (total {len(data)})')
    print('TOTAL added:', total_added)

if __name__ == '__main__':
    main()
